function beep(type='click'){
 if(!sound||effectsVolume<=0||!hostVisible||document.hidden)return;try{ctx||=new AudioContext();ctx.resume();const now=ctx.currentTime;
 const tone=(frequency,delay=0,duration=.12,volume=.035,wave='triangle',to=frequency)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.type=wave;o.frequency.setValueAtTime(frequency,now+delay);o.frequency.exponentialRampToValueAtTime(Math.max(20,to),now+delay+duration);g.gain.setValueAtTime(.001,now+delay);g.gain.linearRampToValueAtTime(volume*effectsVolume,now+delay+.025);g.gain.exponentialRampToValueAtTime(.001,now+delay+duration);o.connect(g).connect(ctx.destination);o.start(now+delay);o.stop(now+delay+duration+.02);};
 const noise=(delay,duration,frequency,volume=.04)=>{const b=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*duration),ctx.sampleRate),data=b.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const src=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();src.buffer=b;filter.type='bandpass';filter.frequency.value=frequency;gain.gain.setValueAtTime(volume*effectsVolume,now+delay);gain.gain.exponentialRampToValueAtTime(.001,now+delay+duration);src.connect(filter).connect(gain).connect(ctx.destination);src.start(now+delay);src.stop(now+delay+duration);};
 if(type==='roll'){for(let i=0;i<8;i++){noise(i*.085,.09,600+i%3*430,.08);tone(180+i%3*80,i*.085,.065,.045,'triangle',65);}return;}
 if(type==='land'){noise(0,.1,350,.09);tone(160,0,.13,.055,'sine',65);tone(880,.13,.11,.025);return;}
 if(type==='open'||type==='close'){noise(0,.2,type==='open'?1700:1050,.055);tone(type==='open'?260:420,.01,.18,.016,'sine',type==='open'?520:190);return;}
 if(type==='bid'){noise(0,.08,500,.08);tone(440,0,.1,.04);tone(660,.09,.15,.03);return;}
 if(type==='pass'||type==='reject'||type==='loanReject'){tone(330,0,.12,.03,'triangle',185);return;}
 if(type==='money'||type==='buy'||type==='accept'||type==='loanAccept'){[660,880,1100].forEach((f,i)=>tone(f,i*.07,.18,.024,'sine'));noise(.12,.05,3500,.02);return;}
 if(type==='build'||type==='redeem'){[330,440,660].forEach((f,i)=>tone(f,i*.085,.14,.03));return;}
 if(['sell','sellGroup','mortgage','loanRepay','settle','jailPay'].includes(type)){[440,330].forEach((f,i)=>tone(f,i*.09,.15,.03));noise(.03,.13,1400,.03);return;}
 if(['offer','loanRequest','loanRate','notice'].includes(type)){tone(520,0,.12,.03,'sine',760);tone(980,.1,.16,.025,'sine');return;}
 if(type==='bankrupt'){tone(160,0,.5,.05,'sawtooth',45);return;}
 if(type==='end'||type==='jailCard'){tone(390,0,.08,.025);tone(520,.08,.13,.025);return;}
 if(type==='error'){tone(140,0,.13,.035,'square');tone(120,.17,.16,.025,'square');return;}
 noise(0,.035,2200,.028);tone(620,0,.045,.015,'triangle',340);
 }catch{}
}
let rollBannerTimer,rollRevealTimer,rollLabelFrame;
function observeSounds(previous,next){
 if(!previous||previous.revision===undefined)return;
 const rolled=next.log?.find(l=>l.id>(previous.log?.at(-1)?.id??0)&&/\d \+ \d/.test(l.text));
 if(rolled){beep('roll');clearTimeout(rollRevealTimer);clearTimeout(rollBannerTimer);$('#roll-banner').hidden=true;const dice=[...next.dice],name=next.players[next.turn].name;rollRevealTimer=setTimeout(()=>{if(menu||!hostVisible)return;beep('land');const el=$('#roll-banner'),total=dice[0]+dice[1],word=total===1?'ход':total>=2&&total<=4?'хода':'ходов';el.textContent=`${total} ${word}!`;el.hidden=false;el.classList.remove('rolled');void el.offsetWidth;el.classList.add('rolled');cancelAnimationFrame(rollLabelFrame);const started=performance.now(),follow=()=>{if(el.hidden||menu||!hostVisible){el.hidden=true;return;}const point=scene?.screenPoint('dice'),r=$('#table').getBoundingClientRect();if(point){el.style.left=(point.x-r.left)+'px';el.style.top=(point.y-r.top)+'px';}if(performance.now()-started<2600)rollLabelFrame=requestAnimationFrame(follow);else el.hidden=true;};follow();},DICE_DURATION);}
 else if(next.lastAction?.id!==previous.lastAction?.id&&next.lastAction)beep(next.lastAction.kind);
}
function showMenu(on){menu=on;if(scene){scene.hostHidden=on||!hostVisible;if(!scene.hostHidden)scene.request();}document.body.classList.toggle('menu',on);$('#welcome').hidden=!on;$('#sidebar').hidden=on||!state;$('#resume').hidden=!session&&!localStorage.getItem('importopoly-local');if(on){clearTimeout(arrivalTimer);clearTimeout(arrivalHide);$('#arrival-banner').hidden=true;clearTimeout(rollRevealTimer);clearTimeout(rollBannerTimer);$('#roll-banner').hidden=true;cancelAnimationFrame(rollLabelFrame);closeCard();eventKey=null;moneyQueue=[];$('#interaction-panel').hidden=true;$('#lobby').hidden=true;$('#modal').hidden=true;}requestAnimationFrame(()=>scene?.resize());}
