async function api(path,body={}){const sent=Date.now();const response=await fetch('./api/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...session,...body})});const data=await response.json();if(Number.isFinite(data.serverNow))serverOffset=data.serverNow-(sent+Date.now())/2;if(!response.ok)throw Object.assign(new Error(data.error),{status:response.status});return data;}
