 const recent=(state.tradeHistory||[]).filter(t=>mode==='local'||[t.from,t.to].includes(m.id)).slice(-6).reverse();if(recent.length)html+='<div class="eyebrow">РЕЗУЛЬТАТЫ ОБМЕНОВ</div>'+recent.map(t=>{const a=state.players.find(p=>p.id===t.from),b=state.players.find(p=>p.id===t.to),label={accepted:'✓ ПРИНЯТ',rejected:'✕ ОТКЛОНЁН',cancelled:'ОТОЗВАН',replaced:'ЗАМЕНЁН',expired:'УСТАРЕЛ'}[t.status];return `<details class="trade-result ${t.status}"><summary><b>${label}</b><span>${esc(a.name)} → ${esc(b.name)}</span></summary><p>Отдавал: ${describeAssets(t.give,t.cashGive)}<br>Просил: ${describeAssets(t.take,t.cashTake)}</p></details>`;}).join('');
 const owned=state.assets.map((a,i)=>a.owner===m.id?i:-1).filter(i=>i>=0);let inventory='';if(owned.length)inventory+=`<div class="eyebrow" style="margin-top:18px">${mode==='local'?'ИМУЩЕСТВО ИГРОКА':'ВАШЕ ИМУЩЕСТВО'}</div><div class="inventory">${owned.map(i=>`<button data-property="${i}" style="--c:${COLORS[BOARD[i].group]||'#617367'}">${BOARD[i].name}${state.assets[i].mortgaged?' ⊘':''}</button>`).join('')}</div>`;
 $('#inventory-panel').innerHTML=inventory||'<div class=eyebrow>ИМУЩЕСТВА ПОКА НЕТ</div>';$('#offers-panel').innerHTML=html;$('#offers-panel').hidden=!html;for(const b of $('#turn-panel').querySelectorAll('[data-action]'))b.onclick=()=>dispatch({kind:b.dataset.action,...(b.dataset.action==='bid'?{amount:Number($('#bid').value)}:{})});for(const b of $('#turn-panel').querySelectorAll('[data-actor]'))b.onclick=()=>{actor=state.players.find(p=>String(p.id)===b.dataset.actor).id;renderTurn();renderProperty();renderEvent();};for(const b of $('#inventory-panel').querySelectorAll('[data-property]'))b.onclick=()=>{openProperty(+b.dataset.property);};if($('#bankruptcy'))$('#bankruptcy').onclick=()=>{dialog('БАНКРОТСТВО',`<h2>Сдать имущество?</h2><p>Вы выйдете из партии. Деньги и активы получит кредитор; при долге банку имущество уйдёт на аукцион.</p><div class="actions"><button id="confirm-bankrupt" class="danger">ДА, Я БАНКРОТ</button></div>`);$('#confirm-bankrupt').onclick=()=>{$('#modal').hidden=true;dispatch({kind:'bankrupt'});};};if($('#finish-menu'))$('#finish-menu').onclick=()=>showMenu(true);if($('#show-event'))$('#show-event').onclick=()=>renderEvent(true);for(const b of document.querySelectorAll('[data-accept-trade],[data-reject-trade]'))b.onclick=()=>{const accept=b.hasAttribute('data-accept-trade'),t=trades().find(t=>t.id===Number(accept?b.dataset.acceptTrade:b.dataset.rejectTrade));dispatch({kind:accept?'accept':'reject',offer:t.id},mode==='local'?(accept?t.to:m.id===t.from?t.from:t.to):m.id);};
