function propertyContent(i){
 const c=BOARD[i],a=state.assets[i],m=me(),owner=state.players.find(p=>p.id===a.owner),buy=canAct()&&state.phase==='buy'&&active().pos===i;
 let html=`<div class="deed-band" style="--c:${COLORS[c.group]||'#657567'}"><small>${c.price?'СВИДЕТЕЛЬСТВО СОБСТВЕННОСТИ':'КЛЕТКА ПОЛЯ'} · № ${String(i).padStart(2,'0')}</small><h2>${esc(c.name)}</h2></div><div class="deed-body">`;
 if(c.price){html+=`<div class="deed-owner">${owner?'ВЛАДЕЛЕЦ: '+esc(owner.name):'БАНК · '+cash(c.price)}${a.mortgaged?' / В ЗАЛОГЕ':''}</div>`;
 if(c.type==='street')html+=`<div class="level-meter" aria-label="Уровень ${a.level} из 5">${Array.from({length:5},(_,j)=>`<span class="${j<a.level?'filled':''}">${j+1}</span>`).join('')}</div><table class="rent-table level-rents"><thead><tr><th>УРОВЕНЬ</th><th>АРЕНДА</th></tr></thead><tbody>${c.rent.map((v,j)=>`<tr class="${j&&j<=a.level?'reached':''} ${a.level===j?'current':''}"><td>${j===0?'Базовый':j+' / '+(j===5?'МАКС.':'5')}</td><td>${cash(v)}</td></tr>`).join('')}</tbody></table><div class="deed-note">Полный цвет: базовая аренда ×2. Повышение уровня: ${cash(c.build)}.</div>`;
 else html+=`<p class="deed-note">${c.type==='rail'?'АРЕНДА: $25 / $50 / $100 / $200 ЗА 1 / 2 / 3 / 4 УЗЛА.':'АРЕНДА: КУБИКИ ×4. ДВА ОБЪЕКТА УСЛУГ — ×10.'}</p>`;
 html+=`<div class="balance-line"><span>ЗАЛОГ / ВЫКУП</span><b>${cash(c.price/2)} / ${cash(Math.ceil(c.price*.55))}</b></div><div class="actions deed-actions">`;
 if(buy)html+=actionButton('buy','КУПИТЬ · '+cash(c.price),true,active().cash<c.price)+actionButton('decline','НА АУКЦИОН');
 if(owner?.id===m.id){const available=canManage();html+=c.type==='street'?actionButton('build',a.level===5?'МАКСИМАЛЬНЫЙ УРОВЕНЬ':'ПОВЫСИТЬ УРОВЕНЬ · '+cash(c.build),true,!available||state.debt?.player===m.id||a.level>=5||!ownsGroup(state,m.id,c.group)||a.mortgaged):'';if(a.level)html+=actionButton('sell','СНИЗИТЬ · +'+cash(c.build/2),false,!available);html+=actionButton(a.mortgaged?'redeem':'mortgage',a.mortgaged?'ВЫКУПИТЬ':'ЗАЛОЖИТЬ',false,!available);if(a.level===5&&buildingStock(state).houses<4)html+=actionButton('sellGroup','ОБНУЛИТЬ ГРУППУ',false,!available);}
 html+='</div>';
 }else{const desc={start:'За проход или остановку — $200.',jail:'В гостях — без последствий. Арест: до трёх попыток дубля, $50 или «Связи».',parking:'Отдых в Дубае. Бесплатных денег здесь нет.',gojail:'Сразу в СИЗО. Без $200 и дополнительного броска.',chance:'Перемещения, выплаты и другие внезапные новости.',chest:'Выплаты, списания и бюрократия.',tax:'Обязательная выплата в банк: '+cash(c.amount||0)+'.'};html+=`<div class="deed-symbol">${{start:'↖',jail:'III',parking:'☀',gojail:'!',chance:'✈',chest:'Г',tax:'$'}[c.type]||'И'}</div><p>${desc[c.type]||''}</p>`;if(canAct()&&state.phase==='card'&&active().pos===i)html+='<button data-own-event class=primary>ОТКРЫТЬ СОБЫТИЕ</button>';}
 return html+'</div>';
}
function playerDialog(title,body){closeCard();const el=$('#interaction-panel');el.innerHTML=`<div class="dialog-head"><span>${esc(title)}</span><button data-close-interaction aria-label="Закрыть">×</button></div><div class="interaction-body">${body}</div>`;el.hidden=false;el.querySelector('[data-close-interaction]').onclick=()=>el.hidden=true;el.scrollIntoView({block:'nearest',behavior:'smooth'});}
$('#trade-open').onclick=()=>{const p=me(),others=state.players.filter(q=>q.id!==p.id&&!q.out);playerDialog('ОБМЕН ИМУЩЕСТВОМ',`<h2>Договоримся.</h2><p>Обмен выполняется целиком после согласия второго игрока. По входящим залогам банк возьмёт 10% суммы залога.</p><label class="field-label" for="trade-target">С КЕМ</label><select id="trade-target">${others.map(q=>`<option value="${q.id}">${esc(q.name)}</option>`).join('')}</select><div id="trade-form"></div>`);const draw=()=>{const q=state.players.find(q=>String(q.id)===$('#trade-target').value);const list=(owner,side)=>state.assets.map((a,i)=>a.owner===owner.id?`<label class="trade-asset"><input type="checkbox" data-side="${side}" value="${i}" ${BOARD[i].type==='street'&&groupCells(BOARD[i].group).some(j=>state.assets[j].level)?'disabled':''}><i style="--c:${COLORS[BOARD[i].group]||'#617367'}"></i>${BOARD[i].name}${a.mortgaged?' ⊘':''}</label>`:'').join('')||'<small>Пока нет имущества</small>';$('#trade-form').innerHTML=`<div class="trade-columns"><div><h3>ОТДАЮ</h3><input id="cash-give" type="number" min="0" max="${p.cash}" value="0" aria-label="Отдаю денег">${list(p,'give')}</div><div><h3>ПОЛУЧАЮ</h3><input id="cash-take" type="number" min="0" max="${q.cash}" value="0" aria-label="Получаю денег">${list(q,'take')}</div></div><div class="actions"><button id="send-offer" class="primary">ПРЕДЛОЖИТЬ ОБМЕН</button></div>`;$('#send-offer').onclick=()=>dispatch({kind:'offer',to:q.id,cashGive:Number($('#cash-give').value),cashTake:Number($('#cash-take').value),give:[...document.querySelectorAll('[data-side=give]:checked')].map(el=>+el.value),take:[...document.querySelectorAll('[data-side=take]:checked')].map(el=>+el.value)});};$('#trade-target').onchange=draw;draw();};
$('#rules-open').onclick=()=>{const stock=buildingStock(state);dialog('КРАТКИЕ ПРАВИЛА',`<h2>Всё как за столом.</h2><div class="rules-grid"><section><h3>ПОБЕДА</h3><p>Последний игрок, который не стал банкротом. Старт — $1500. Проход СТАРТА — $200.</p></section><section><h3>ПОКУПКА И АРЕНДА</h3><p>Свободный объект можно купить. Отказались — аукцион для всех. Аренда списывается автоматически.</p></section><section><h3>УРОВНИ</h3><p>Соберите весь цвет. Повышайте уровни равномерно, максимум до 5. Красные секции показывают уровень и рост аренды. Уровни 1–4 расходуют по одному жетону, уровень 5 заменяет четыре жетона одной печатью.</p></section><section><h3>ЗАЛОГ</h3><p>Получаете половину цены. Аренда отключается. Выкуп — сумма залога +10%. Сначала обнулите уровни цветовой группы.</p></section><section><h3>СИЗО</h3><p>Три дубля подряд — арест. Выход: дубль, $50 или «Связи». После третьей неудачной попытки платите $50 и идёте по выпавшим кубикам. Аренда продолжает приходить.</p></section><section><h3>НЕ ХВАТАЕТ ДЕНЕГ</h3><p>Снижайте уровни за половину цены или закладывайте имущество. При банкротстве перед игроком залоги наследуются без разовой комиссии. Перед банком — аукцион.</p></section><section><h3>ОБМЕНЫ</h3><p>Имущество и обмены доступны в чужой ход и при долге, кроме аукциона. Обмен не отменяет долг: после сделки погасите платёж. По одному исходящему предложению на игрока; новое заменяет предыдущее. Предложения сохраняются до ответа. Сначала снизьте уровни всей группы. Получатель залога сразу платит банку 10% его суммы, обычный выкуп остаётся отдельным.</p></section><section><h3>СМЕНА ХОДА</h3><p>После завершённого действия ход передаётся автоматически. Дубль даёт ещё один бросок. Покупка, событие, аукцион и погашение долга ждут решения.</p></section><section><h3>РЕЗЕРВ УЛУЧШЕНИЙ</h3><p>Осталось ${stock.houses} из 32 жетонов и ${stock.hotels} из 12 печатей 5 уровня. Бесплатных денег за Дубай нет.</p></section></div>`);};
