function cardAction(e){
 if(e.cash!==undefined)return(e.cash>=0?'ПОЛУЧИТЬ ':'ЗАПЛАТИТЬ ')+cash(Math.abs(e.cash));
 if(e.release)return 'СОХРАНИТЬ СВЯЗИ';if(e.jail)return 'ОТПРАВИТЬСЯ В СИЗО';if(e.repair)return 'ОПЛАТИТЬ РЕМОНТ';return 'ПЕРЕМЕСТИТЬ ФИГУРКУ';
}
function decisionKey(){if(!state||menu)return null;if(state.phase==='auction'&&state.auction)return `auction:${state.auction.id??state.round+':'+state.turn+':'+state.auction.index}`;if(!canAct())return null;if(state.phase==='buy')return `buy:${state.round}:${state.turn}:${active().pos}:${state.animation?.id??0}`;if(state.phase==='card'&&state.drawn)return `event:${state.drawn.id??state.round}:${state.drawn.type}:${state.drawn.index}`;return null;}
function closeCard(){clearTimeout(cardTimer);cardTimer=null;const el=$('#event-popup'),view=cardView;cardView=null;if(!el.hidden&&view){beep('close');const node=el.querySelector('.card-launch'),r=node?.getBoundingClientRect();if(node&&r&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const clone=node.cloneNode(true);clone.classList.add('closing-card');clone.inert=true;clone.setAttribute('aria-hidden','true');clone.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));Object.assign(clone.style,{position:'fixed',left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',margin:'0',pointerEvents:'none',zIndex:15,animation:'none'});document.body.append(clone);const point=cardOrigin(view),dx=point.x-r.left-r.width/2,dy=point.y-r.top-r.height/2;const anim=clone.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:`translate(${dx}px,${dy}px) rotateZ(14deg) rotateY(90deg) scale(.08)`,opacity:0}],{duration:420,easing:'cubic-bezier(.5,0,.8,.4)'});anim.onfinish=()=>clone.remove();}}el.hidden=true;}
function cardOrigin(view){return scene?.screenPoint(view.index??active().pos)||{x:innerWidth/2,y:innerHeight/2};}
let cardVariant=0;
function launchCard(view){const node=$('#event-popup .card-launch'),variant=cardVariant++%3;view.angle=[-4,3.5,-2,5,-3][(cardVariant-1)%5];view.offset={x:0,y:0};node.style.setProperty('--rest-angle',view.angle+'deg');const r=node.getBoundingClientRect(),point=cardOrigin(view),dx=point.x-r.left-r.width/2,dy=point.y-r.top-r.height/2;beep('open');if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const turns=[-165,165,-280],tilt=[-16,18,-8];const anim=node.animate([{transform:`translate(${dx}px,${dy}px) rotateX(58deg) rotateY(${turns[variant]}deg) rotateZ(${tilt[variant]}deg) scale(.1)`,opacity:.3},{offset:.55,transform:`translate(${dx*.18}px,${dy*.18-28}px) rotateX(12deg) rotateY(${turns[variant]*.25}deg) rotateZ(${-tilt[variant]*.3}deg) scale(.82)`,opacity:1},{transform:`translate(0,0) rotateZ(${view.angle}deg) scale(1)`,opacity:1}],{duration:[850,980,1100][variant],easing:'cubic-bezier(.18,.7,.2,1)'});anim.onfinish=()=>{node.dataset.landed='true';};}bindCardDrag(node,view);}
function bindCardDrag(node,view){let drag=null;
 node.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button,input,select,a')||!e.target.closest('.deed-band,.event-heading,.event-emblem'))return;node.getAnimations().forEach(a=>a.cancel());drag={id:e.pointerId,x:e.clientX,y:e.clientY,start:{...view.offset}};node.setPointerCapture(e.pointerId);node.classList.add('dragging');e.preventDefault();});
 node.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const r=$('#event-popup').getBoundingClientRect(),w=node.offsetWidth,h=node.offsetHeight,maxX=Math.max(8,Math.min(110,(r.width-w)/2-10)),maxY=Math.max(8,Math.min(80,(r.height-h)/2-10));view.offset={x:Math.max(-maxX,Math.min(maxX,drag.start.x+e.clientX-drag.x)),y:Math.max(-maxY,Math.min(maxY,drag.start.y+e.clientY-drag.y))};node.style.setProperty('--drag-x',view.offset.x+'px');node.style.setProperty('--drag-y',view.offset.y+'px');});
 const end=e=>{if(drag?.id!==e.pointerId)return;drag=null;node.classList.remove('dragging');};node.addEventListener('pointerup',end);node.addEventListener('pointercancel',end);
}
var arrivalTimer,arrivalHide;
function showArrival(previous,next){const event=next.arrival;if(!previous||!event||event.id===previous.arrival?.id)return;clearTimeout(arrivalTimer);clearTimeout(arrivalHide);const r=next.players.find(p=>p.id===event.player),wait=scene?.presentationRemaining()||0;arrivalTimer=setTimeout(()=>{if(menu||!hostVisible)return;beep('error');const el=$('#arrival-banner');el.innerHTML=`<strong>${esc(event.title)}</strong><span>${esc(r?.name)} — ${esc(event.text)}</span>`;el.hidden=false;el.classList.remove('arrived');void el.offsetWidth;el.classList.add('arrived');arrivalHide=setTimeout(()=>el.hidden=true,4800);},Math.max(0,wait-30));}


