function auctionContent(){const a=state.auction,m=me(),lead=state.players.find(p=>p.id===a.leader),cell=BOARD[a.index],eligible=!m.out&&!a.passed.includes(m.id);if(auctionChoiceKey!==a.id){auctionChoiceKey=a.id;auctionIncrement=10;}return `<div class="deed-band" style="--c:${COLORS[cell.group]||'#64776a'}"><small>ОТКРЫТЫЙ АУКЦИОН</small><h2>${esc(cell.name)}</h2></div><div class="deed-body"><div class="auction-price">${cash(a.bid)}</div><div class="deed-owner">${lead?'ЛИДИРУЕТ: '+esc(lead.name):'СТАВОК ПОКА НЕТ'}</div><div class="auction-players">${state.players.filter(p=>!p.out).map(p=>`<span class="${a.passed.includes(p.id)?'passed':''}">${esc(p.name)} · ${a.passed.includes(p.id)?'ПАС':a.leader===p.id?'ЛИДЕР':'В ТОРГАХ'}</span>`).join('')}</div>${mode==='local'?`<div class="actor-switch">${state.players.filter(p=>!p.out&&!p.bot).map(p=>`<button data-auction-actor="${p.id}" class="${m.id===p.id?'chosen':''}" ${a.passed.includes(p.id)?'disabled':''}>${esc(p.name)}</button>`).join('')}</div>`:''}<div class="auction-clock" role="timer" aria-label="До закрытия аукциона"><span>ДО ЗАКРЫТИЯ</span><b data-auction-seconds>5.0 С</b><i><em data-auction-progress></em></i></div><div class="actions auction-quick"><button class="primary" data-bid-increment="10" ${!eligible||m.cash<a.bid+10?'disabled':''}>СТАВКА +10 $</button>${actionButton('pass','ПАС',false,!eligible||a.leader===m.id)}</div><div class="auction-slider"><label for="auction-step">ПРИБАВКА <output id="auction-step-label">+${auctionIncrement} $</output></label><input id="auction-step" type="range" min="1" max="100" step="1" value="${auctionIncrement}" ${!eligible?'disabled':''}><div class="auction-range"><span>1 $</span><span>100 $</span></div><button id="auction-custom-bid" ${!eligible||m.cash<a.bid+auctionIncrement?'disabled':''}>ПОСТАВИТЬ ${cash(a.bid+auctionIncrement)}</button></div><p class="deed-note">${a.passed.includes(m.id)?'Вы вышли из этих торгов. Ждём остальных.':'Новая ставка даёт ещё 5 секунд. По таймеру лот забирает лидер; без ставок он остаётся в банке.'}</p></div>`;}
function positionCard(){const el=$('#event-popup');if(el.hidden)return;const r=$('#table').getBoundingClientRect(),mobile=innerWidth<=650;const left=mobile?0:r.left,top=mobile?Math.max(38,Math.min(r.top,80)):Math.max(32,r.top),width=mobile?innerWidth:r.width,height=mobile?innerHeight-top-18:Math.min(r.bottom,innerHeight)-top;Object.assign(el.style,{left:left+'px',top:top+'px',width:width+'px',height:height+'px'});el.style.setProperty('--card-height',Math.max(180,height-30)+'px');}
function paintCard(animate){
 if(!cardView||!state)return;const el=$('#event-popup'),isAuction=cardView.type==='auction',isProperty=cardView.type==='property',d=state.drawn;
 if(!isAuction&&!isProperty&&(!d||!canAct())){closeCard();return;}
 const content=isAuction?auctionContent():isProperty?propertyContent(cardView.index):`<div class="event-heading">${d.type==='chance'?'ТЕЛЕГРАМ-КАНАЛЫ':'ГОСУСЛУГИ'}</div><div class="event-inner"><div class="event-emblem">${d.type==='chance'?'✈':'Г'}</div><h2>${esc(d.title)}</h2><p>${esc(d.text)}</p><div class="effect">${effectText(d.effect)}</div><div class="actions">${actionButton('card',cardAction(d.effect),true,!canAct())}</div></div>`;
 const body=`<button class="card-dismiss" aria-label="Закрыть карточку">×</button>${content}`;
 if(animate||el.hidden||!el.querySelector('.card-front')){el.innerHTML=`<div class="card-launch"><div class="flying-card ${isProperty?'property-card':'event-paper'}" role="dialog" aria-label="${isProperty?'Карточка участка':'Карточка события'}"><div class="card-back" aria-hidden="true"><span>ИМПОРТО<br>ПОЛИЯ</span><small>${isAuction?'АУКЦИОН':isProperty?'СОБСТВЕННОСТЬ':d.type==='chance'?'ТЕЛЕГРАМ':'ГОСУСЛУГИ'}</small></div><div class="card-front">${body}</div></div></div>`;el.hidden=false;}
 else {const front=el.querySelector('.card-front'),top=front.scrollTop,bid=el.querySelector('#bid'),draft=bid?.value,focused=document.activeElement===bid;if(front.innerHTML!==body){front.innerHTML=body;front.scrollTop=top;const next=el.querySelector('#bid');if(next&&draft!==undefined){next.value=draft;if(focused)next.focus();}}}
 positionCard();if(animate)launchCard(cardView);el.querySelector('.card-dismiss').onclick=()=>{closeCard();eventKey=null;};for(const b of el.querySelectorAll('[data-action]'))b.onclick=()=>dispatch({kind:b.dataset.action,...(isProperty?{index:cardView.index}:{}),...(b.dataset.action==='bid'?{amount:Number($('#bid').value)}:{})});for(const b of el.querySelectorAll('[data-auction-actor]'))b.onclick=()=>{actor=state.players.find(p=>String(p.id)===b.dataset.auctionActor).id;render();};for(const b of el.querySelectorAll('[data-bid-increment]'))b.onclick=()=>dispatch({kind:'bid',increment:Number(b.dataset.bidIncrement),auctionId:state.auction?.id});const slider=el.querySelector('#auction-step'),custom=el.querySelector('#auction-custom-bid');if(slider){slider.oninput=()=>{auctionIncrement=Number(slider.value);el.querySelector('#auction-step-label').textContent='+'+auctionIncrement+' $';custom.textContent='ПОСТАВИТЬ '+cash(state.auction.bid+auctionIncrement);custom.disabled=me().out||state.auction.passed.includes(me().id)||me().cash<state.auction.bid+auctionIncrement;};custom.onclick=()=>dispatch({kind:'bid',increment:auctionIncrement,auctionId:state.auction?.id});}updateAuctionClock();const own=el.querySelector('[data-own-event]');if(own)own.onclick=()=>renderEvent(true);
}
