$('#event-popup').addEventListener('click',e=>{if(e.target===$('#event-popup'))closeCard();});
document.addEventListener('pointerdown',()=>{if(ctx?.state==='suspended'&&sound)ctx.resume();},{capture:true});
if(scene){scene.followEnabled=localStorage.getItem('importopoly-follow')!=='false';$('#follow-camera').setAttribute('aria-pressed',String(scene.followEnabled));$('#follow-camera').textContent=scene.followEnabled?'◉ АВТОКАМЕРА':'○ АВТОКАМЕРА';}
function animateProposals(){
 const events=state.proposalEvents||[],latest=events.at(-1)?.id||0;if(proposalCursor===null){proposalCursor=latest;return;}const fresh=events.filter(e=>e.id>proposalCursor);proposalCursor=latest;if(menu||!hostVisible)return;
 fresh.slice(-3).forEach((event,i)=>setTimeout(()=>{if(menu||!hostVisible)return;const player=id=>state.players.find(p=>p.id===id),from=player(event.from),to=player(event.to);if(!from||!to)return;const node=document.createElement('div');node.className='proposal-notice';if(/ПРИНЯТ|ОТКЛОНЁН|ОТОЗВАН/.test(event.label)){toast(event.label+' · '+from.name+' → '+to.name);beep(event.label.includes('ПРИНЯТ')?'buy':'error');}node.innerHTML=`<b>✉</b><span>${esc(from.name)} → ${esc(to.name)}<small>${esc(event.label)}</small></span>`;$('#money-layer').append(node);
 const find=id=>[...document.querySelectorAll('[data-player-id]')].find(el=>el.dataset.playerId===String(id)),a=find(event.from)?.getBoundingClientRect(),b=find(event.to)?.getBoundingClientRect();if(a&&b&&a.top>0&&b.bottom<innerHeight&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const letter=document.createElement('div');letter.className='flying-envelope';letter.textContent='✉';$('#money-layer').append(letter);const animation=letter.animate([{transform:`translate(${a.left+30}px,${a.top+20}px) rotate(-20deg) scale(.4)`},{offset:.5,transform:`translate(${Math.max(30,a.left-90)}px,${(a.top+b.top)/2}px) rotateY(180deg) scale(1.4)`},{transform:`translate(${b.left+30}px,${b.top+20}px) rotate(12deg) scale(.6)`}],{duration:1100,easing:'ease-in-out'});animation.onfinish=()=>letter.remove();find(event.to)?.animate([{boxShadow:'0 0 0 3px #aa5935'},{boxShadow:'0 0 0 0px transparent'}],{duration:1600});}setTimeout(()=>node.remove(),2800);
 },i*650));
}
function animateMoney(){
 const events=state.moneyEvents||[],latest=events.at(-1)?.id||0;
 if(moneyCursor===null){moneyCursor=latest;return;}
 const fresh=events.filter(e=>e.id>moneyCursor);moneyCursor=latest;
 if(menu||!hostVisible)return;moneyQueue.push(...fresh);moneyQueue=moneyQueue.slice(-12);playMoney();
}
function playerAnchor(id){const el=[...document.querySelectorAll('[data-player-id]')].find(p=>p.dataset.playerId===String(id)),r=el?.getBoundingClientRect();if(r&&r.top>36&&r.bottom<innerHeight-24)return {x:r.right-65,y:r.top+r.height/2};const point=scene?.screenPoint(0,id);if(point?.visible)return point;return null;}
function playMoney(){
 if(moneyPlaying||!moneyQueue.length)return;const e=moneyQueue.shift();if(menu||!hostVisible){moneyQueue=[];return;}moneyPlaying=true;beep('money');const layer=$('#money-layer'),nodes=[],name=id=>id===null?'БАНК':state.players.find(p=>p.id===id)?.name||'ИГРОК';
 for(const [id,sign,other] of [[e.from,-1,e.to],[e.to,1,e.from]]){if(id===null)continue;const node=document.createElement('div');node.className='player-money '+(sign>0?'incoming':'outgoing');node.innerHTML=`<b>${sign>0?'+':'−'}${cash(e.amount)}</b><small>${sign>0?'ОТ':'→'} ${esc(name(other))}</small><small>${esc(e.reason)}</small>`;layer.append(node);nodes.push({id,node});}
 const started=performance.now();const follow=()=>{const t=performance.now()-started;for(const {id,node}of nodes){const p=playerAnchor(id);node.hidden=!p;if(p){node.style.left=Math.max(8,Math.min(innerWidth-175,p.x-90))+'px';node.style.top=Math.max(38,p.y-25-Math.min(24,t/80))+'px';}}if(t<1900&&!menu&&hostVisible)requestAnimationFrame(follow);else{nodes.forEach(({node})=>node.remove());moneyPlaying=false;playMoney();}};follow();
 const start=playerAnchor(e.from??e.to),end=playerAnchor(e.to??e.from);if(start&&end&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const bill=document.createElement('div');bill.className='flying-money';bill.textContent='$';layer.append(bill);if(e.from===null){start.x-=80;start.y-=30;}if(e.to===null){end.x-=80;end.y-=30;}const animation=bill.animate([{transform:`translate(${start.x}px,${start.y}px) rotate(-18deg)`,opacity:0},{offset:.25,opacity:1},{offset:.55,transform:`translate(${(start.x+end.x)/2-20}px,${(start.y+end.y)/2-35}px) rotate(12deg)`,opacity:1},{transform:`translate(${end.x}px,${end.y}px) scale(.5)`,opacity:0}],{duration:850,easing:'ease-in-out'});animation.onfinish=()=>bill.remove();}
}

document.addEventListener('click',e=>{const button=e.target.closest('button');if(parent===window&&button&&!button.disabled&&!button.matches('[data-action],.card-dismiss,[data-property],#sound'))beep('click');});

// Load the music only after interaction; one audio element survives menus and turns.
const backgroundMusic=new Audio();backgroundMusic.loop=true;backgroundMusic.preload='none';backgroundMusic.volume=.28;
let musicUnlocked=false,musicStarting=false;
function musicAllowed(){return musicUnlocked&&musicEnabled&&musicVolume>0&&hostVisible&&!document.hidden;}
function syncMusic(){
 backgroundMusic.volume=musicVolume;
 if(!musicAllowed()){backgroundMusic.pause();return;}
 if(!backgroundMusic.getAttribute('src'))backgroundMusic.src=new URL('./importopoly.mp3',import.meta.url).href;
 if(!backgroundMusic.paused||musicStarting)return;musicStarting=true;
 backgroundMusic.play().then(()=>{if(!musicAllowed())backgroundMusic.pause();}).catch(()=>{}).finally(()=>{musicStarting=false;});
}
function unlockMusic(){musicUnlocked=true;syncMusic();}
document.addEventListener('pointerdown',unlockMusic,{passive:true});
document.addEventListener('keydown',unlockMusic);
document.addEventListener('visibilitychange',syncMusic);
addEventListener('pagehide',()=>backgroundMusic.pause());
addEventListener('pageshow',syncMusic);
$('#sound').textContent=sound?'♫':'♪';$('#sound').title=sound?'Выключить звук':'Включить звук';

// A passive deed follows the current player without taking over the inspection dialog.
function renderWatch(){
 const el=$('#watch-card');if(!state||menu||state.phase==='finished'){el.hidden=true;return;}
 const presentation=state.presentation,showing=presentation&&Date.now()<presentation.until;
 const p=state.players.find(p=>p.id===(showing?presentation.player:active().id))||active();
 const index=showing?presentation.index:p.pos,c=BOARD[index]||BOARD[p.pos],asset=state.assets[index],owner=state.players.find(p=>p.id===asset?.owner),d=!showing&&state.phase==='card'?state.drawn:null;
 const labels={roll:p.jailed?'ВЫХОД ИЗ СИЗО':'ГОТОВИТСЯ БРОСИТЬ',buy:'ВЫБИРАЕТ ПОКУПКУ',card:'РАЗЫГРЫВАЕТ СОБЫТИЕ',auction:'АУКЦИОН',debt:'ПОГАШАЕТ ПЛАТЁЖ'};
 const html='<small>'+esc(p.name)+' · '+(showing?'ЗАВЕРШАЕТ ДЕЙСТВИЕ':labels[state.phase]||'ХОДИТ')+'</small><h3>'+esc(d?.title||c.name)+'</h3>'+(d?'<p>'+esc(d.text)+'</p>':'<div class="watch-level" style="--c:'+(COLORS[c.group]||'#71806b')+'">'+(c.price?cash(c.price)+' · '+(owner?esc(owner.name):'БАНК'):'КЛЕТКА '+index)+(asset?.level?' · УР. '+asset.level:'')+'</div>')+'<button data-watch-index="'+index+'">ОСМОТРЕТЬ ↗</button>';
 if(el.innerHTML!==html){el.innerHTML=html;el.querySelector('button').onclick=()=>openProperty(index);}el.hidden=false;
}
var turnUiReady=0;
setInterval(()=>{if(!state||menu||!hostVisible)return;renderWatch();if(turnUiReady!==state.actionReadyAt&&Date.now()>=(state.actionReadyAt||0)){turnUiReady=state.actionReadyAt;renderTurn();if(cardView)paintCard(false);} },180);

addEventListener('message',async e=>{if(e.origin!==location.origin||e.source!==parent||e.data?.type!=='importopoly-social')return;const {id,action,code,roomId}=e.data;try{if(busy)throw Error('Дождись окончания действия.');busy=true;let result;if(action==='prepare'){if(mode!=='online'||!session){if(state&&state.phase!=='finished'&&!menu)throw Error('Закончи локальную партию или открой меню.');enterOnline(await api('create',{name:$('#name').value,piece}));}const invitation=await api('invite');result={code:session.code,token:session.token,roomId:invitation.roomId};}else if(action==='join'){if(mode==='online'&&session?.code===code){showMenu(false);receive(await api('state'));}else {if(state&&state.phase!=='finished'&&!menu)throw Error('Сначала выйди в меню текущей партии.');enterOnline(await api('join',{code,roomId,name:$('#name').value,piece}));}result={ok:true};}else throw Error('Неизвестная команда.');parent.postMessage({type:'importopoly-social-result',id,result},location.origin);}catch(error){parent.postMessage({type:'importopoly-social-result',id,error:error.message},location.origin);}finally{busy=false;}});

let localBotAt=0;setInterval(()=>{if(mode!=='local'||!state||menu||busy||!hostVisible||document.hidden||Date.now()<(state.actionReadyAt||0)+650||Date.now()<localBotAt)return;const next=nextBotAction(state);if(!next)return;localBotAt=Date.now()+800;dispatch(next.action,next.id);},350);

document.addEventListener('click',e=>{if(!e.target.closest('[data-invite]'))return;if(parent!==window)parent.postMessage({type:'importopoly-invite'},location.origin);else toast('Приглашения друзьям доступны в приложении на MAKSON PROJECT. Код комнаты можно отправить вручную.');});

function updateAuctionClock(){if(state?.phase!=='auction'||!state.auction)return;const remaining=Math.max(0,state.auction.deadline-Date.now()-(mode==='online'?serverOffset:0));const label=$('[data-auction-seconds]'),bar=$('[data-auction-progress]');if(label)label.textContent=(remaining/1000).toFixed(1)+' С';if(bar)bar.style.transform='scaleX('+Math.min(1,remaining/5000)+')';}
setInterval(()=>{if(!state)return;if(mode==='local'&&!busy){const expired=expireAuction(state);if(expired!==state){state=expired;actor=null;localStorage.setItem('importopoly-local',JSON.stringify(state));if(!menu)render();}}if(!menu&&hostVisible)updateAuctionClock();},100);

